import { describe, expect, it } from 'vitest';
import { arenaBlockers, SHRINE_WALK, SHRINES, shrineBounds, shrineCell, shrineCells, shrineFind } from '../src/core/shrines';
import { LEGENDS } from '../src/core/legends';
import { REGION_DEFS } from '../src/core/map/regionDefs';
import { ValleyMap, type RegionDef } from '../src/core/map/valley';
import { T } from '../src/core/map/tiles';
import { RITUALS } from '../src/core/rituals';

// V22 legendary shrines, step 1 (LEGENDARY_SHRINES.md): the designed layouts (data/world/shrines.json, generated by
// scripts/gen-shrines.py) are stamped onto the maps in place of the old 12-pillar rings — walls, water, lava, the
// court's floor and rune lines, pillars, statues, braziers / crystals, the altar. Each one must stand clear of the
// map's authored things, be walkable from the map spawn, and keep its arena free of anything but the planned cover.

const maps = new Map<string, ValleyMap>();
const mapOf = (id: string) => { if (!maps.has(id)) maps.set(id, new ValleyMap(REGION_DEFS[id])); return maps.get(id)!; };
const sites = Object.entries(REGION_DEFS).flatMap(([region, d]) => (d.legendaries ?? []).filter((l) => l.shrine).map((l) => ({ region, l })));
const N4 = [[1, 0], [-1, 0], [0, 1], [0, -1]];

function blocked(m: ValleyMap): Set<string> {
  const s = new Set<string>();
  for (let cy = 0; cy < Math.ceil(m.heightTiles / m.chunk); cy++) for (let cx = 0; cx < Math.ceil(m.widthTiles / m.chunk); cx++)
    for (const o of m.objectsInChunk(cx, cy)) if (o.collideR || o.kind === 'tree' || o.kind === 'boulder') s.add(`${Math.floor(o.x)},${Math.floor(o.y)}`);
  return s;
}
const reached = new Map<string, Set<string>>();
function reach(region: string): Set<string> {
  if (reached.has(region)) return reached.get(region)!;
  const m = mapOf(region), d = REGION_DEFS[region], b = blocked(m);
  // a shrine's own cracked wall (Mew's ruins) counts as solved: BFS "after the shrine's puzzle" (§5)
  for (const f of d.field ?? []) if (f.look !== 'crack') b.add(`${f.x},${f.y}`);
  // a plane (one walled pocket per shrine) is entered at every hidden entrance's arrival
  const starts = [[d.spawn.x, d.spawn.y], ...Object.values(REGION_DEFS).flatMap((o) => (o.secrets ?? []).filter((s) => s.to === region).map((s) => [s.toX, s.toY]))];
  const seen = new Set(starts.map(([x, y]) => `${x},${y}`)), q = starts.map((p) => [...p]);
  while (q.length) {
    const [x, y] = q.pop()!;
    for (const [dx, dy] of N4) {
      const nx = x + dx, ny = y + dy, k = `${nx},${ny}`;
      if (seen.has(k) || m.solidAt(nx, ny) || b.has(k)) continue;
      seen.add(k); q.push([nx, ny]);
    }
  }
  reached.set(region, seen);
  return seen;
}
const near = (s: Set<string>, x: number, y: number) => s.has(`${x},${y}`) || N4.some(([dx, dy]) => s.has(`${x + dx},${y + dy}`));

describe('V22 shrines: layouts', () => {
  it('30 designed layouts, rectangular, each with a ritual spot; every arena free of all but its cover', () => {
    // the two shrine gates (Kyogre, Temple) became hidden entrances (LEGENDARY_SHRINES.md mục 8)
    expect(SHRINES.size).toBe(30);
    for (const s of SHRINES.values()) {
      const w = s.rows[0].length;
      expect(s.rows.every((r) => r.length === w), s.id).toBe(true);
      expect(shrineFind(s, 'P'), s.id).not.toBeNull();
      expect(s.rows[s.anchor[1]]?.[s.anchor[0]], s.id).toBeTruthy();
      expect([1, 2, 3, 4]).toContain(s.tier);
      expect(LEGENDS.get(s.legend), s.id).toBeTruthy();
      expect(arenaBlockers(s), s.id).toEqual([]);
      if (s.arena) expect(SHRINE_WALK.has(s.rows[s.anchor[1]][s.anchor[0]]) || s.cover.includes(s.rows[s.anchor[1]][s.anchor[0]]), s.id).toBe(true);
    }
  });

  it('tiers follow the design: the box legends are tier 1, the mythicals tier 4', () => {
    for (const id of ['lugia', 'ho-oh', 'groudon', 'rayquaza', 'giratina', 'mewtwo']) expect(SHRINES.get(id)!.tier, id).toBe(1);
    for (const id of ['articuno', 'zapdos', 'moltres', 'regirock', 'regice', 'registeel', 'regigigas', 'heatran', 'azelf', 'uxie']) expect(SHRINES.get(id)!.tier, id).toBe(2);
    for (const id of ['mew', 'celebi', 'jirachi', 'shaymin', 'darkrai', 'deoxys', 'manaphy']) expect(SHRINES.get(id)!.tier, id).toBe(4);
  });

  it('the footprint fades into the map at the corners but every wall / shore next to the court stays', () => {
    const rq = SHRINES.get('rayquaza')!; // cliffs all round, a spiral stair in the south
    expect(shrineCell(rq, 0, 0)).toBeNull();
    const regi = SHRINES.get('regice')!; // a closed rectangular tomb: the wall round the room stays
    expect(shrineCell(regi, 1, 1)).toBe('#');
    for (const s of SHRINES.values()) s.rows.forEach((row, y) => [...row].forEach((ch, x) => {
      if (!SHRINE_WALK.has(ch)) return;
      for (const [dx, dy] of N4) if (s.rows[y + dy]?.[x + dx] !== undefined) expect(shrineCell(s, x + dx, y + dy), `${s.id} ${x + dx},${y + dy}`).not.toBeNull();
    }));
  });
});

describe('V22 shrines: on the maps', () => {
  it('every shrine of the design stands on its map (planes included); legends.json points at the fight spot', () => {
    // all in planes since the hidden shrines: fights, meetings, Manaphy's reef, the Lati / Mesprit triggers
    expect(sites.length).toBe(30);
    expect(new Set(sites.map((x) => x.l.shrine)).size).toBe(SHRINES.size);
    for (const { region, l } of sites) {
      const s = SHRINES.get(l.shrine!)!;
      expect(s, l.id).toBeTruthy();
      expect(s.legend === l.id || s.id === l.id, l.id).toBe(true);
      expect(s.region, l.id).toBe(REGION_DEFS[region].void ? 'instanced' : region);
      const mode = RITUALS.get(s.id)?.mode ?? 'fight';
      if (mode !== 'fight' && mode !== 'gift') continue;
      const site = LEGENDS.get(l.id)!.site!;
      expect({ x: site.x, y: site.y, region: site.region }, l.id).toEqual({ x: l.x, y: l.y, region });
      // the approach radius matches the arena (it was a fixed 330 px for the stone rings)
      if (s.arena) expect(l.arena, l.id).toBe((s.arena - 1) * 48);
    }
  });

  it('no Vietnam map and no map overloaded; two shrines never overlap', () => {
    // gates and roaming triggers are not counted (LEGENDARY_SHRINES.md §1.2: "4 (+1 cổng muộn)")
    const per = new Map<string, number>();
    for (const { region, l } of sites) {
      const mode = RITUALS.get(l.shrine!)?.mode;
      if (mode !== 'portal' && mode !== 'roam') per.set(region, (per.get(region) ?? 0) + 1);
    }
    for (const [region, n] of per) {
      expect(REGION_DEFS[region].theme, region).not.toBe('mekong');
      expect(n, region).toBeLessThanOrEqual(4);
    }
    for (const region of per.keys()) {
      const seen = new Map<string, string>();
      for (const l of REGION_DEFS[region].legendaries ?? []) {
        if (!l.shrine) continue;
        const [x0, y0, x1, y1] = shrineBounds(SHRINES.get(l.shrine)!, l.x, l.y);
        const d = REGION_DEFS[region];
        expect(x0 >= 2 && y0 >= 2 && x1 < d.width - 2 && y1 < d.height - 2, `${l.id} inside the map`).toBe(true);
        for (const c of shrineCells(SHRINES.get(l.shrine)!, l.x, l.y)) {
          const k = `${c.tx},${c.ty}`;
          expect(seen.get(k), `${l.id} overlaps at ${k}`).toBeUndefined();
          seen.set(k, l.id);
        }
      }
    }
  });

  it('stamped terrain: walls are solid, the court is walkable, the arena holds only the planned cover', () => {
    for (const { region, l } of sites) {
      const s = SHRINES.get(l.shrine!)!, m = mapOf(region), b = blocked(m);
      const [x0, y0] = shrineBounds(s, l.x, l.y);
      for (const c of shrineCells(s, l.x, l.y)) {
        if (c.ch === '#') expect(m.terrainAt(c.tx, c.ty), `${l.id} wall ${c.tx},${c.ty}`).toBe(T.Wall);
        if (c.ch === 'L') expect(m.terrainAt(c.tx, c.ty)).toBe(T.Lava);
        if ('.:=+P&'.includes(c.ch)) expect(m.solidAt(c.tx, c.ty), `${l.id} ${c.ch} ${c.tx},${c.ty}`).toBe(false);
      }
      if (!s.arena) continue;
      for (let y = 0; y < s.rows.length; y++) for (let x = 0; x < s.rows[y].length; x++) {
        if (Math.hypot(x - s.anchor[0], y - s.anchor[1]) > s.arena - 1 || s.cover.includes(s.rows[y][x])) continue;
        const tx = x0 + x, ty = y0 + y;
        expect(m.solidAt(tx, ty) || (b.has(`${tx},${ty}`) && !(tx === l.x && ty === l.y)), `${l.id} arena ${tx},${ty}`).toBe(false);
      }
    }
  });

  it('no procedural trees inside a shrine; its own pillars, statues and altar are there', () => {
    for (const { region, l } of sites) {
      const s = SHRINES.get(l.shrine!)!, m = mapOf(region);
      const cells = new Set([...shrineCells(s, l.x, l.y)].map((c) => `${c.tx},${c.ty}`));
      const objs: { id: string; x: number; y: number }[] = [];
      for (let cy = 0; cy < Math.ceil(m.heightTiles / m.chunk); cy++) for (let cx = 0; cx < Math.ceil(m.widthTiles / m.chunk); cx++) objs.push(...m.objectsInChunk(cx, cy));
      const inside = objs.filter((o) => cells.has(`${Math.floor(o.x)},${Math.floor(o.y)}`));
      expect(inside.filter((o) => /^t-/.test(o.id)).map((o) => o.id), l.id).toEqual([]);
      const own = inside.filter((o) => o.id.startsWith(`shrine-${l.id}-`));
      const want = [...shrineCells(s, l.x, l.y)].filter((c) => 'OoS*AT&12B'.includes(c.ch)).length;
      expect(own.length, l.id).toBe(want);
      // the altar on the arena centre has no collider (the legendary appears there)
      const altar = own.find((o) => (o as { data?: { prop?: string } }).data?.prop === 'altar' && o.x === l.x && o.y === l.y) as { collideR?: number } | undefined;
      if (altar) expect(altar.collideR).toBe(0);
    }
  });

  it('every ritual spot and arena can be walked to from the map spawn; the map\'s own things stay reachable', () => {
    for (const { region, l } of sites) {
      const s = SHRINES.get(l.shrine!)!, r = reach(region);
      const [x0, y0] = shrineBounds(s, l.x, l.y), p = shrineFind(s, 'P')!;
      expect(near(r, x0 + p[0], y0 + p[1]), `${l.id} ritual spot`).toBe(true);
      if (s.arena) expect(near(r, l.x, l.y), `${l.id} arena`).toBe(true);
    }
    for (const region of new Set(sites.map((x) => x.region))) {
      const d: RegionDef = REGION_DEFS[region], r = reach(region), m = mapOf(region);
      const things = [...d.npcs, ...d.trainers, ...d.waypoints, ...(d.portals ?? []), ...d.chests.filter((c) => !c.requiresFlag), ...d.dungeons];
      for (const o of things) {
        expect(m.solidAt(o.x, o.y), `${region} ${o.id} on a wall`).toBe(false);
        expect(near(r, o.x, o.y) || near(r, o.x, o.y + 1), `${region} ${o.id} reachable`).toBe(true);
      }
    }
  });
});
